    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "彼はいつも（　　）に先生の話を聞きながら、メモを取っている。",
    "sentenceFurigana": "彼はいつも（　　）に先生の話を聞きながら、メモを取っている。",
