    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "A：来月から映画の値段が高くなりますね。<br>B：（　　）。",
    "sentenceFurigana": "A：来月から映画の値段が高くなりますね。<br>B：（　　）。",
