    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "3歳の子どもでも（　　）説明すれば、理解してくれる。",
    "sentenceFurigana": "3歳の子どもでも（　　）説明すれば、理解してくれる。",
