    "explanation": "大学毕业时写的长篇文章，称为「卒業論文」最自然。「レポート」是课堂作业中写的短篇文章，「作文」是写自己想法或经历的短篇文章，所以大学毕业所需的正式研究文章要用「論文」。虽然也会用「ペーパー」这个词，但毕业时一般说「論文」，这是非常礼貌的说法哦。",
    "sourceId": "N3V0089"
