    "no": 87,
    "packId": "cj-vocab-325",
    "level": "N3",
    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "人を（　　）で判断するのはよくないと言われるが、なかなか難しいものだ。",
