    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "いつも静かな彼が大きな声で歌ったので、（　　）でした。",
    "sentenceFurigana": "いつも静かな彼が大きな声で歌ったので、（　　）でした。",
    "options": [
      "当然",
      "平凡",
      "意外",
      "同様"
    ],
    "answer": 3,
    "translation": "平时很安静的他大声唱歌，所以真让人意外。",
    "explanation": "正确答案是「意外」。「意外」指与预想不同、令人惊讶。平时很安静的人大声唱歌，所以适合用这个词。「当然」指这样发展是理所当然的事，「平凡」指不特别，「同様」指相同或相似，都不能表达惊讶。完整的句子是「いつも静かな彼が大きな声で歌ったので、意外でした。」（平时很安静的他大声唱歌，所以真让人意外。）",
