    "level": "N3",
    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "彼は疲れているのか、授業中によく（　　）して、先生に叱られている。",
    "sentenceFurigana": "彼は疲れているのか、授業中によく（　　）して、先生に叱られている。",
