    "level": "N3",
    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "一人で抱え込まず、困ったときは周りの人を（　　）ください。",
    "sentenceFurigana": "一人で抱え込まず、困ったときは周りの人を（　　）ください。",
