    "explanation": "正确答案是「ざっと」。「ざっと」表示大致地浏览一遍。也就是说，没有逐字细读，而是在短时间内了解整体内容。「ずっと」表示长时间持续，「じっと」表示一动不动、集中注意力的样子，「きっと」表示有把握的推测。「没有时间详细阅读」是表示大致浏览的线索。完整的句子是「详读的时间不够，所以我大致浏览了一下资料。」",
