    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "A：実は、学校をやめるかもしれません。<br>B：（　　）。",
    "sentenceFurigana": "A：実は、学校をやめるかもしれません。<br>B：（　　）。",
