    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "A：あ、ハンカチが落ちましたよ。<br>B：（　　）。",
    "sentenceFurigana": "A：あ、ハンカチが落ちましたよ。<br>B：（　　）。",
