    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "最初は疑問でしたが、詳しい説明を聞いて、理由が分かり（　　）しました。",
    "sentenceFurigana": "最初は疑問でしたが、詳しい説明を聞いて、理由が分かり（　　）しました。",
