    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "深呼吸をすると、緊張していた気持ちが少し（　　）ました。",
    "sentenceFurigana": "深呼吸をすると、緊張していた気持ちが少し（　　）ました。",
