    "level": "N3",
    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "書類を急いで読んだため、重要な注意書きを（　　）しまいました。",
    "sentenceFurigana": "書類を急いで読んだため、重要な注意書きを（　　）しまいました。",
