    "type": "語彙",
    "part": 1,
    "partName": "語彙・文脈",
    "unit": 1,
    "sentence": "不眠で悩んでいたが、枕を変えたら（　　）眠れるようになった。",
    "sentenceFurigana": "不眠で悩んでいたが、枕を変えたら（　　）眠れるようになった。",
