    "translation": "并不是完全不吃肉。我也吃肉，只是蔬菜吃得更多而已。",
    "explanation": "正解は「わけではない」です。「わけではない」は、そう断定するのは違うと、思い込みを否定します。肉も食べることを明言して、完全に避けているわけではないと説明します。「つもりだ」は意思、「はずだ」は予想、「ことにした」は決定で、いずれも全く食べないことを肯定するため合いません。完成文は「肉を全く食べないわけではない。肉も食べるが、野菜を多めにしているだけだ。」です。",
    "sourceId": "N3G0213"
