    "type": "文法",
    "part": 1,
    "partName": "文法・文法形式",
    "unit": 1,
    "sentence": "両親が優秀だからといって、子どもも優秀だ（　　）。",
    "sentenceFurigana": "両親が優秀だからといって、子どもも優秀だ（　　）。",
