    "no": 127,
    "packId": "cj-grammar-241",
    "level": "N3",
    "type": "文法",
    "part": 1,
    "partName": "文法・文法形式",
    "unit": 1,
    "sentence": "今、出かける（　　）です。靴を履いているので、少し待ってください。",
