    "level": "N3",
    "type": "文法",
    "part": 1,
    "partName": "文法・文法形式",
    "unit": 1,
    "sentence": "私の孫は会う（　　）かわいくなるので、将来が楽しみだ。",
    "sentenceFurigana": "私の孫は会う（　　）かわいくなるので、将来が楽しみだ。",
