    "part": 1,
    "partName": "文法・文法形式",
    "unit": 1,
    "sentence": "友だちに漫画の本を（　　）まま、ずっと返していないのを思い出した。",
    "sentenceFurigana": "友だちに漫画の本を（　　）まま、ずっと返していないのを思い出した。",
