    "no": 216,
    "packId": "cj-grammar-241",
    "level": "N3",
    "type": "文法",
    "part": 1,
    "partName": "文法・文法形式",
    "unit": 1,
    "sentence": "来週のパーティーに（　　）、早めに教えてください。",
